import{_ as i,o,c as l,a4 as t}from"./chunks/framework.BAT2SzCK.js";const g=JSON.parse('{"title":"🎥 视频监控中心概述","description":"","frontmatter":{},"headers":[],"relativePath":"media/overview.md","filePath":"media/overview.md","lastUpdated":1794271174000}'),a={name:"media/overview.md"};function r(n,e,s,d,c,_){return o(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="🎥-视频监控中心概述" tabindex="-1">🎥 视频监控中心概述 <a class="header-anchor" href="#🎥-视频监控中心概述" aria-label="Permalink to &quot;🎥 视频监控中心概述&quot;">​</a></h1><p><code>yudao-module-media</code> 是 MzMedia 专为解决工业安防、园区监控与物联网跨系统视频联动而设计的流媒体中枢。</p><hr><h2 id="核心能力矩阵" tabindex="-1">核心能力矩阵 <a class="header-anchor" href="#核心能力矩阵" aria-label="Permalink to &quot;核心能力矩阵&quot;">​</a></h2><ol><li><strong>国标 GB/T 28181-2016/2022 全栈支持</strong>： <ul><li>支持主流品牌（海康威视、大华股份、宇视科技等）IPC 网络摄像机、NVR 硬盘录像机无缝通过 SIP 协议注册接入；</li><li>覆盖设备注册鉴权、心跳保活、通道目录检索、状态查询与报警通知。</li></ul></li><li><strong>ZLMediaKit 流媒体集群纳管</strong>： <ul><li>自动分配 RTP 动态接收端口（<code>30000-30500</code>）；</li><li>将设备推送的 PS/RTP 流实时解复用并转换为 <strong>WebRTC、HTTP-FLV、WS-FLV、HLS</strong> 多协议格式；</li><li>提供 REST API 与 Webhook 回调机制（推流鉴权、播放统计、无人观看自动停流）。</li></ul></li><li><strong>低延迟网页点播与云台控制</strong>： <ul><li>深度集成 <strong>Jessibuca</strong> 播放器，延迟稳定低于 1 秒；</li><li>网页端提供全功能 PTZ 云台控制轮盘，支持八向转动、焦距调整、光圈变倍与 <strong>0x81 预置位调用</strong>；</li><li>支持浏览器麦克风声音采集并通过 G.711A/U 进行<strong>双向语音对讲</strong>。</li></ul></li><li><strong>与物联网（IoT）深度跨域联动</strong>： <ul><li>传感器（烟感、温度、周界红外等）上报异常时，秒级发布系统事件 <code>IotMediaLinkageEvent</code>；</li><li>驱动就近球机快速对准报警现场并触发快照抓拍，告警消息卡片直达移动端。</li></ul></li></ol>',5)])])}const m=i(a,[["render",r]]);export{g as __pageData,m as default};
